// Reward / Dopamine system
//
// This implements the artificial dopamine/reward signal that drives learning.
// The reward is generated by the ENVIRONMENT when the fly successfully interacts
// with the flag. It is NOT generated by the fly's neural system directly.
//
// DATA SOURCE CLASSIFICATION:
// - DAN neuron types (PAM, PPL1): REAL (from Aso et al. 2014, Liu et al. 2012)
// - DAN → KC→MBON modulation circuit: REAL (from Takemura et al. 2017)
// - Dopamine dynamics model: APPROXIMATED (simplified decay, not biophysical)
// - Reward function (flag interaction → reward): INVENTED (our experimental design)
// - Plasticity rule (dopamine-modulated Hebbian): APPROXIMATED
//
// The reward pathway:
// 1. Environment detects successful flag interaction
// 2. Reward signal is generated (magnitude depends on experiment mode)
// 3. Dopamine neurons (DANs) in the neural network are activated
// 4. DAN activity releases "dopamine" (tracked as dopamineLevel)
// 5. Dopamine modulates KC→MBON synaptic plasticity
// 6. Modified synapses change future behavior probability

import { NeuralNetwork } from './neural';
import { ExperimentConfig, ExperimentMode } from './types';
import { MODE_REWARD_MULTIPLIERS } from './config';

export class RewardSystem {
  network: NeuralNetwork;
  config: ExperimentConfig;
  // Current reward state
  currentReward: number = 0;
  cumulativeReward: number = 0;
  dopamineLevel: number = 0;
  rewardCooldownRemaining: number = 0;
  // Reward history
  rewardHistory: { time: number; magnitude: number }[] = [];
  dopamineHistory: { time: number; level: number }[] = [];
  // Delayed reward queue
  pendingRewards: { time: number; magnitude: number }[] = [];
  // Random reward timer
  randomRewardTimer: number = 0;
  // Mode tracking
  wasTrained: boolean = false;
  trainingPhase: boolean = true;

  constructor(network: NeuralNetwork, config: ExperimentConfig) {
    this.network = network;
    this.config = config;
    this.network.dopamineDecay = config.dopamineDecay;
    this.network.learningRate = config.learningRate;
  }

  updateConfig(config: ExperimentConfig) {
    this.config = config;
    this.network.dopamineDecay = config.dopamineDecay;
    this.network.learningRate = config.learningRate;
  }

  // Called when the fly successfully interacts with the flag
  // This is the ONLY place reward is generated (besides random_reward mode)
  onFlagInteraction(time: number): void {
    const mode = this.config.mode;

    // Handle reward_removed mode: train first, then remove
    if (mode === 'reward_removed') {
      if (this.trainingPhase) {
        this.trainingPhase = this.cumulativeReward < 10.0; // Train until 10 cumulative reward
        if (!this.trainingPhase) return; // Reward removed after training
      } else {
        return; // No reward after training phase
      }
    }

    // Skip reward in random control mode
    if (mode === 'random') return;

    const multiplier = MODE_REWARD_MULTIPLIERS[mode] || 1.0;
    const reward = this.config.rewardStrength * multiplier;

    if (mode === 'delayed_reward') {
      // Queue reward for delayed delivery
      this.pendingRewards.push({
        time: time + 2.0, // 2 second delay
        magnitude: reward,
      });
    } else {
      this.deliverReward(reward, time);
    }
  }

  // Deliver reward signal to the neural system
  private deliverReward(magnitude: number, time: number): void {
    if (this.rewardCooldownRemaining > 0) return;

    this.currentReward = magnitude;
    this.cumulativeReward += magnitude;
    this.rewardHistory.push({ time, magnitude: magnitude });

    // Activate dopamine neurons in the neural network
    this.network.releaseDopamine(magnitude);
    this.dopamineLevel = this.network.dopamineLevel;

    // Set cooldown
    this.rewardCooldownRemaining = this.config.rewardCooldown;
  }

  // Update reward system state (called each simulation step)
  update(dt: number, time: number): void {
    // Decay current reward
    this.currentReward *= (1 - 0.05 * dt * 60);

    // Update cooldown
    if (this.rewardCooldownRemaining > 0) {
      this.rewardCooldownRemaining -= dt;
      if (this.rewardCooldownRemaining < 0) this.rewardCooldownRemaining = 0;
    }

    // Track dopamine level from network
    this.dopamineLevel = this.network.dopamineLevel;
    this.dopamineHistory.push({ time, level: this.dopamineLevel });
    if (this.dopamineHistory.length > 1000) this.dopamineHistory.shift();

    // Process delayed rewards
    for (let i = this.pendingRewards.length - 1; i >= 0; i--) {
      if (time >= this.pendingRewards[i].time) {
        this.deliverReward(this.pendingRewards[i].magnitude, time);
        this.pendingRewards.splice(i, 1);
      }
    }

    // Random reward mode: give rewards unrelated to behavior
    if (this.config.mode === 'random_reward') {
      this.randomRewardTimer += dt;
      if (this.randomRewardTimer > 5.0 + Math.random() * 10.0) {
        this.randomRewardTimer = 0;
        this.deliverReward(this.config.rewardStrength, time);
      }
    }
  }

  // Get reward system state for display
  getState() {
    return {
      currentReward: this.currentReward,
      cumulativeReward: this.cumulativeReward,
      dopamineLevel: this.dopamineLevel,
      rewardCooldown: this.rewardCooldownRemaining,
      rewardHistory: this.rewardHistory,
      dopamineHistory: this.dopamineHistory,
    };
  }

  reset() {
    this.currentReward = 0;
    this.cumulativeReward = 0;
    this.dopamineLevel = 0;
    this.rewardCooldownRemaining = 0;
    this.rewardHistory = [];
    this.dopamineHistory = [];
    this.pendingRewards = [];
    this.randomRewardTimer = 0;
    this.trainingPhase = true;
  }
}
